import type { Catalog } from './connection.ts';

export function renderModule(connection: string, catalog: Catalog): string {
  if (!/^[a-z][a-z0-9_-]*$/i.test(connection)) {
    throw new Error(`Invalid connection name: ${JSON.stringify(connection)}`);
  }

  const lines = [
    '// Generated by pnpm flags:sync. Do not edit.',
    "import 'server-only';",
    "import { connections } from '../flags.config.ts';",
    "import { createFlag } from '../flags/next.ts';",
    '',
  ];

  for (const [index, [key, flag]] of Object.entries(catalog.flags)
    .sort(([left], [right]) => left.localeCompare(right, 'en'))
    .entries()) {
    // Use private identifiers, so keys can include punctuation or reserved words.
    const local = `flag_${index}`;
    if (flag.description) {
      lines.push(
        '/**',
        ...flag.description
          .replace(/\*\//g, '*\\/')
          .split(/\r?\n/)
          .map((line) => ` * ${line}`),
        ' */',
      );
    }
    lines.push(
      `const ${local} = createFlag(connections[${JSON.stringify(connection)}], ${JSON.stringify(key)}, ${JSON.stringify(flag.variants)} as const, ${JSON.stringify(catalog.id)});`,
      `export { ${local} as ${JSON.stringify(key)} };`,
      '',
    );
  }

  return lines.join('\n');
}
